<?php
require_once __DIR__ . '/includes/layout.php';
$user=require_login();$schoolId=tenant_id();
$metrics=[];foreach(['students','teachers','classes','attendance'] as $table){try{$stmt=db()->prepare("SELECT COUNT(*) FROM {$table} WHERE school_id=:school_id");$stmt->execute(['school_id'=>$schoolId]);$metrics[$table]=(int)$stmt->fetchColumn();}catch(Throwable){$metrics[$table]=0;}}
$pending=0;try{$stmt=db()->prepare("SELECT COALESCE(SUM(amount-paid_amount),0) FROM fee_invoices WHERE school_id=:school_id AND status IN ('pending','partial')");$stmt->execute(['school_id'=>$schoolId]);$pending=(float)$stmt->fetchColumn();}catch(Throwable){}
$recent=[];try{$stmt=db()->prepare('SELECT action,entity,created_at FROM audit_logs WHERE school_id=:school_id ORDER BY id DESC LIMIT 8');$stmt->execute(['school_id'=>$schoolId]);$recent=$stmt->fetchAll();}catch(Throwable){}
admin_header('Dashboard');?><div class="content"><div class="cards"><div class="card"><div class="label">Total students</div><div class="metric"><?= $metrics['students'] ?></div></div><div class="card"><div class="label">Total teachers</div><div class="metric"><?= $metrics['teachers'] ?></div></div><div class="card"><div class="label">Total classes</div><div class="metric"><?= $metrics['classes'] ?></div></div><div class="card"><div class="label">Pending fees</div><div class="metric"><?= e(number_format($pending,2)) ?></div></div></div><div class="panel"><div class="panel-head"><h2>Today's attendance</h2><a class="btn secondary" href="attendance.php">Open attendance</a></div><p class="metric"><?= $metrics['attendance'] ?></p><p class="empty">Live tenant-scoped attendance records in the current workspace.</p></div><div class="panel"><div class="panel-head"><h2>Recent activity</h2></div><div class="table-wrap"><table><thead><tr><th>Action</th><th>Entity</th><th>Time</th></tr></thead><tbody><?php foreach($recent as $item):?><tr><td><?=e($item['action'])?></td><td><?=e($item['entity'])?></td><td><?=e($item['created_at'])?></td></tr><?php endforeach;if(!$recent):?><tr><td class="empty" colspan="3">No activity has been recorded yet.</td></tr><?php endif;?></tbody></table></div></div></div><?php admin_footer();
